glsl1.vert:
precision highp float;
uniform highp mat4 cc_matView;
  uniform highp mat4 cc_matProj;
  uniform highp mat4 cc_matViewProj;
  uniform highp vec4 cc_cameraPos;
#if USE_LOCAL
  uniform highp mat4 cc_matWorld;
#endif
#if SAMPLE_FROM_RT
  #define QUATER_PI         0.78539816340
  #define HALF_PI           1.57079632679
  #define PI                3.14159265359
  #define PI2               6.28318530718
  #define PI4               12.5663706144
  #define INV_QUATER_PI     1.27323954474
  #define INV_HALF_PI       0.63661977237
  #define INV_PI            0.31830988618
  #define INV_PI2           0.15915494309
  #define INV_PI4           0.07957747155
  #define EPSILON           1e-6
  #define EPSILON_LOWP      1e-4
  #define LOG2              1.442695
  #define EXP_VALUE         2.71828183
  #define FP_MAX            65504.0
  #define FP_SCALE          0.0009765625
  #define FP_SCALE_INV      1024.0
  #define GRAY_VECTOR       vec3(0.299, 0.587, 0.114)
        #define LIGHT_MAP_TYPE_DISABLED 0
  #define LIGHT_MAP_TYPE_ALL_IN_ONE 1
  #define LIGHT_MAP_TYPE_INDIRECT_OCCLUSION 2
  #define REFLECTION_PROBE_TYPE_NONE 0
  #define REFLECTION_PROBE_TYPE_CUBE 1
  #define REFLECTION_PROBE_TYPE_PLANAR 2
  #define REFLECTION_PROBE_TYPE_BLEND 3
  #define REFLECTION_PROBE_TYPE_BLEND_AND_SKYBOX 4
      #define LIGHT_TYPE_DIRECTIONAL 0.0
  #define LIGHT_TYPE_SPHERE 1.0
  #define LIGHT_TYPE_SPOT 2.0
  #define LIGHT_TYPE_POINT 3.0
  #define LIGHT_TYPE_RANGED_DIRECTIONAL 4.0
  #define IS_DIRECTIONAL_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_DIRECTIONAL)) < EPSILON_LOWP)
  #define IS_SPHERE_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_SPHERE)) < EPSILON_LOWP)
  #define IS_SPOT_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_SPOT)) < EPSILON_LOWP)
  #define IS_POINT_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_POINT)) < EPSILON_LOWP)
  #define IS_RANGED_DIRECTIONAL_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_RANGED_DIRECTIONAL)) < EPSILON_LOWP)
  #define TONE_MAPPING_ACES 0
  #define TONE_MAPPING_LINEAR 1
  #define SURFACES_MAX_TRANSMIT_DEPTH_VALUE 999999.0
  #ifndef CC_SURFACES_DEBUG_VIEW_SINGLE
    #define CC_SURFACES_DEBUG_VIEW_SINGLE 1
  #endif
  #ifndef CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC
    #define CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC 2
  #endif
#endif
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec4 color;
varying vec2 uv0;
varying float v_glyphT;
vec4 vert () {
  vec4 pos = vec4(a_position, 1.0);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  #if USE_PIXEL_ALIGNMENT
    pos = cc_matView * pos;
    pos.xyz = floor(pos.xyz);
    pos = cc_matProj * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  uv0 = a_texCoord;
  #if SAMPLE_FROM_RT
    uv0 = cc_cameraPos.w > 1.0 ? vec2(uv0.x, 1.0 - uv0.y) : uv0;
  #endif
  color = a_color;
  v_glyphT = a_color.r;
  color = vec4(a_color.g, a_color.g, a_color.g, a_color.a);
  return pos;
}
void main() { gl_Position = vert(); }

glsl1.frag:
#ifdef GL_OES_standard_derivatives
#extension GL_OES_standard_derivatives: enable
#endif
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture2D(tex, uv).rgb, texture2D(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture2D(tex, uv);
#endif
}
#if USE_ALPHA_TEST
      uniform float alphaThreshold;
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
varying vec4 color;
varying vec2 uv0;
varying float v_glyphT;
#if USE_TEXTURE
  uniform sampler2D cc_spriteTexture;
#endif
   uniform vec4 faceTopColor;
   uniform vec4 faceBottomColor;
   uniform vec4 innerGlowColor;
   uniform vec4 fill2Color;
   uniform vec4 shadow2Color;
   uniform vec4 fill3Color;
   uniform vec4 shadow3Color;
   uniform vec4 outerGlowColor;
   uniform vec2 textureSize;
   uniform vec2 shadow2Offset;
   uniform vec2 shadow3Offset;
   uniform float innerGlowBlur;
   uniform float innerGlowOpacity;
   uniform float faceHalfHeight;
   uniform float faceCenterY;
   uniform float expand2;
   uniform float expand3;
   uniform float shadow2Blur;
   uniform float shadow3Blur;
   uniform float outerGlowBlur;
   uniform float outerGlowOpacity;
   uniform float pxRange;
   uniform float pxScale;
   uniform float edgeSoftness;
float sampleSdf(vec2 uv) {
  #if USE_TEXTURE
    vec4 c = CCSampleWithAlphaSeparated(cc_spriteTexture, uv);
    return max(c.a, max(c.r, max(c.g, c.b)));
  #else
    return 0.0;
  #endif
}
float sampleDist(vec2 uv) {
  return (sampleSdf(uv) - 0.5) * pxRange;
}
float aaPx(float sdf) {
  float ds = length(vec2(dFdx(sdf), dFdy(sdf)));
  return max(ds * pxRange, 0.75);
}
float coverage(float distPx, float sdf, float softPx) {
  float aa = max(aaPx(sdf) * 0.92, softPx * 0.55);
  return smoothstep(-aa, aa, distPx);
}
float faceCoverage(vec2 uv, vec2 texel, float softPx) {
  float sdf0 = sampleSdf(uv);
  float w = max(fwidth(sdf0) * 0.9, softPx / max(pxRange, 1.0));
  w = max(w, 1.5 / max(pxRange, 1.0));
  float acc = smoothstep(0.5 - w, 0.5 + w, sdf0);
  vec2 o1 = vec2(0.5, 0.5) * texel;
  vec2 o2 = vec2(-0.5, 0.5) * texel;
  vec2 o3 = vec2(0.5, -0.5) * texel;
  vec2 o4 = vec2(-0.5, -0.5) * texel;
  acc += smoothstep(0.5 - w, 0.5 + w, sampleSdf(uv + o1));
  acc += smoothstep(0.5 - w, 0.5 + w, sampleSdf(uv + o2));
  acc += smoothstep(0.5 - w, 0.5 + w, sampleSdf(uv + o3));
  acc += smoothstep(0.5 - w, 0.5 + w, sampleSdf(uv + o4));
  return acc / 5.0;
}
float shadowCoverage(vec2 uv, float expandPx, float blurPx, vec2 texel, float centerSdf, float softPx) {
  float aa = max(aaPx(centerSdf) * 0.88, softPx * 0.4);
  if (blurPx <= 0.15) {
    return smoothstep(-aa, aa, sampleDist(uv) + expandPx);
  }
  float sum = 0.0;
  float wsum = 0.0;
  float sigma = max(blurPx * 0.5, 0.2);
  float tap = blurPx * 0.55;
  for (int y = -2; y <= 2; ++y) {
    for (int x = -2; x <= 2; ++x) {
      vec2 od = vec2(float(x), float(y));
      float w = exp(-dot(od, od) / (2.0 * sigma * sigma));
      vec2 ouv = uv + od * tap * texel;
      sum += smoothstep(-aa, aa, sampleDist(ouv) + expandPx) * w;
      wsum += w;
    }
  }
  return sum / max(wsum, 1e-5);
}
vec4 over(vec4 src, vec4 dst) {
  float outA = src.a + dst.a * (1.0 - src.a);
  vec3 outRgb = (src.rgb * src.a + dst.rgb * dst.a * (1.0 - src.a)) / max(outA, 1e-5);
  return vec4(outRgb, outA);
}
float outerGlowAlpha(float distPx, float blurPx) {
  if (blurPx <= 0.1) return 0.0;
  float outside = max(-distPx, 0.0);
  float a = 1.0 - smoothstep(0.0, max(blurPx, 0.1), outside);
  float maxOutside = max(pxRange * 0.5 - 1.0, 1.0);
  float edgeFade = 1.0 - smoothstep(maxOutside * 0.82, maxOutside, outside);
  float outsideOnly = 1.0 - smoothstep(0.0, 1.2, distPx);
  return a * edgeFade * outsideOnly;
}
vec4 frag () {
  vec4 o = vec4(0.0);
  #if USE_TEXTURE
    vec2 texSize = max(textureSize, vec2(1.0));
    vec2 texel = 1.0 / texSize;
    float scale = pxScale;
    float e2 = expand2 * scale;
    float e3 = expand3 * scale;
    float b2 = shadow2Blur * scale;
    float b3 = shadow3Blur * scale;
    float gBlur = innerGlowBlur * scale;
    float outlineSoft = edgeSoftness * scale * 0.85;
    float faceSoft = edgeSoftness * scale;
    vec2 sh2 = vec2(shadow2Offset.x, shadow2Offset.y) * scale * texel;
    vec2 sh3 = vec2(shadow3Offset.x, shadow3Offset.y) * scale * texel;
    float sdf = sampleSdf(uv0);
    float d = (sdf - 0.5) * pxRange;
    float haloBlur = outerGlowBlur * scale;
    float haloA = outerGlowAlpha(d, haloBlur) * outerGlowOpacity * outerGlowColor.a;
    o = over(vec4(outerGlowColor.rgb, haloA), o);
    float a3s = shadowCoverage(uv0 - sh3, e3, b3, texel, sdf, outlineSoft);
    float a3f = coverage(d + e3, sdf, outlineSoft);
    o = over(vec4(shadow3Color.rgb, a3s * shadow3Color.a), o);
    o = over(vec4(fill3Color.rgb, a3f * fill3Color.a), o);
    float a2s = shadowCoverage(uv0 - sh2, e2, b2, texel, sdf, outlineSoft);
    float a2f = coverage(d + e2, sdf, outlineSoft);
    o = over(vec4(shadow2Color.rgb, a2s * shadow2Color.a), o);
    o = over(vec4(fill2Color.rgb, a2f * fill2Color.a), o);
    float faceA = faceCoverage(uv0, texel, faceSoft);
    float faceInset = smoothstep(0.0, outlineSoft * 0.35, max(d, 0.0));
    faceA *= faceInset;
    float halfH = max(faceHalfHeight, 0.01);
    float t = clamp(0.5 + (v_glyphT - 0.5 - faceCenterY) / (halfH * 2.0), 0.0, 1.0);
    t = pow(t, 0.72);
    vec3 gradRgb = mix(faceBottomColor.rgb, faceTopColor.rgb, t);
    float rim = 1.0 - smoothstep(0.0, max(gBlur * 0.42, 0.9), max(d, 0.0));
    rim = pow(clamp(rim, 0.0, 1.0), 1.15);
    vec3 faceRgb = mix(gradRgb, shadow2Color.rgb, rim * 0.22);
    float hi = pow(clamp(v_glyphT, 0.0, 1.0), 1.35) * (1.0 - rim * 0.45);
    faceRgb = mix(faceRgb, faceTopColor.rgb, hi * 0.2);
    float dGlow = max(d, 0.0);
    float sigma = max(gBlur * 0.4, 0.35);
    float gx = dGlow / (sigma * 1.4142136);
    float softCenter = clamp(1.0 - exp(-gx * (0.92 + 0.28 * gx)), 0.0, 1.0);
    softCenter = pow(softCenter, 0.72);
    float hollowA = faceA * (1.0 - softCenter * innerGlowOpacity);
    hollowA = clamp(hollowA, 0.0, 0.75);
    o = over(vec4(faceRgb, faceA), o);
    o = over(vec4(innerGlowColor.rgb, hollowA), o);
  #endif
  o *= color;
  ALPHA_TEST(o);
  return o;
}
void main() { gl_FragColor = frag(); }
